contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        address ownerBefore = c.owner(); if (__ESBMC_reverted()) return;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint contractBalanceBefore = address(c).balance;
        uint callerBalanceBefore = address(this).balance;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint contractBalanceAfter = address(c).balance;
        uint callerBalanceAfter = address(this).balance;

        assert(
            reverted
                ? (contractBalanceAfter == contractBalanceBefore
                    && callerBalanceAfter == callerBalanceBefore
                    && c.owner() == ownerBefore
                    && c.depositsCount() == depositsBefore)
                : (contractBalanceBefore >= contractBalanceAfter
                    && contractBalanceBefore - contractBalanceAfter == callerBalanceAfter - callerBalanceBefore
                    && contractBalanceAfter == 0
                    && c.owner() == ownerBefore
                    && c.depositsCount() == depositsBefore)
        );
    }

    receive() external payable {}
}

